"""m04 conceptual items (origin 'bo_sung'): true/false and multiple-choice questions derived from the lecturer's slides (Ch.4 p.3-55); each names the slide it comes from.
They are NOT lecturer questions.  Numbers that appear (3.76, ignition temperatures, 5-15 %, 21/79) are read from the slide images."""
import os, sys
sys.path.insert(0, os.path.dirname(__file__))
from m04_common import *
ITEMS = []
def S(pg, topic_vi, topic_en): return dict(vi=f'Bổ sung – từ slide Ch.4 tr.{pg}: {topic_vi}', en=f'Added – from slide Ch.4 p.{pg}: {topic_en}')
def T(vi, en): return dict(vi=vi, en=en)
TP = dict(basic=T('Nhiên liệu và phản ứng cháy', 'Fuels and combustion reaction'), af=T('Tỉ lệ AF và cân bằng phản ứng', 'AF and balancing'),
          air=T('Không khí lý thuyết và thừa', 'Theoretical and excess air'), dew=T('Điểm sương sản phẩm cháy', 'Dew point of products'),
          rev=T('Phân tích cháy ngược', 'Reverse combustion analysis'), enth=T('Entanpi cháy và nhiệt trị', 'Enthalpy of combustion, HHV/LHV'))
def add(x): ITEMS.append(x)
def Q(vi, en): return B(vi, en)

add(tf(Q('Trong phản ứng cháy, số nguyên tử của mỗi nguyên tố được bảo toàn nhưng tổng số mol nói chung KHÔNG bảo toàn.', 'In a combustion reaction the number of atoms of each element is conserved but the total number of moles in general is NOT.'), True,
       B('Đúng. Khối lượng và số nguyên tử của từng nguyên tố được bảo toàn (tr.11); tổng số mol thì không. Ví dụ C + O₂ → CO₂ có 2 kmol chất phản ứng và 1 kmol sản phẩm; C₈H₁₈ + 20(O₂ + 3,76 N₂) có 96,2 kmol vào và 99,7 kmol ra.', 'True. The mass and the number of atoms of each element are conserved (p.11); the total number of moles is not. For example C + O₂ → CO₂ has 2 kmol of reactants and 1 kmol of product; C₈H₁₈ + 20(O₂ + 3.76 N₂) has 96.2 kmol in and 99.7 kmol out.'),
       1, TP['af'], S(11, 'bảo toàn khối lượng, không bảo toàn số mol', 'mass is conserved, moles are not'), 'bo_sung', 'slide p.11 + Ví dụ 15–1'))
add(mcq(Q('Slide Ch.4 tr.5–6: không khí khô được xấp xỉ gồm 21 % O₂ và 79 % N₂ theo số mol. Số kmol N₂ đi kèm mỗi kmol O₂ là:', 'Slide Ch.4 p.5–6: dry air is approximated as 21 percent O₂ and 79 percent N₂ by mole. The kmol of N₂ that accompany each kmol of O₂ is:'),
        [opt('3.76'), opt('0.27'), opt('4.76'), opt('3.29')], 0, B('0,79/0,21 = 3,76 kmol N₂ trên mỗi kmol O₂ (tr.6). 4,76 là số kmol KHÔNG KHÍ trên mỗi kmol O₂ (1 + 3,76); 0,27 = 0,21/0,79 đảo ngược; 3,29 = 79/24 là phép chia sai.', '0.79/0.21 = 3.76 kmol of N₂ per kmol of O₂ (p.6). 4.76 is the kmol of AIR per kmol of O₂ (1 + 3.76); 0.27 = 0.21/0.79 is inverted; 3.29 = 79/24 is a wrong division.'),
        1, TP['basic'], S(6, '1 kmol O₂ đi kèm 3,76 kmol N₂', '1 kmol O₂ comes with 3.76 kmol N₂'), 'bo_sung', 'slide p.6'))
add(mcq(Q('Slide Ch.4 tr.7: vì sao N₂ trong không khí, dù là khí trơ, vẫn ảnh hưởng mạnh tới kết quả của quá trình cháy?', 'Slide Ch.4 p.7: why does the N₂ of the air, although inert, still affect the outcome of combustion strongly?'),
        [opt('Vì nó vào buồng đốt với lượng lớn ở nhiệt độ thấp và ra ở nhiệt độ cao hơn nhiều, hấp thụ một phần lớn năng lượng hóa học giải phóng.'), opt('Vì nó phản ứng với nhiên liệu tạo ra lượng lớn NO nên làm tăng nhiệt trị.'), opt('Vì nó làm tăng nồng độ O₂ ở vùng cháy.'), opt('Vì nó thay đổi hệ số hợp thức của cacbon.')], 0,
        B('Slide tr.7: N₂ vào lượng lớn ở nhiệt độ thấp, ra ở nhiệt độ cao hơn rất nhiều nên hấp thụ phần lớn năng lượng hóa học giải phóng (nhiệt độ ngọn lửa thấp hơn khi có N₂). Chỉ một lượng rất nhỏ N₂ tạo oxit nitơ; nó không làm tăng nhiệt trị và không đổi hệ số hợp thức.', 'Slide p.7: N₂ enters in large quantity at low temperature and leaves at a much higher one, so it absorbs a large share of the chemical energy released (the flame is cooler with N₂ present). Only a very small amount forms nitric oxides; it neither raises the heating value nor changes the stoichiometric coefficients.'),
        1, TP['basic'], S(7, 'N₂ hấp thụ năng lượng', 'N₂ absorbs energy'), 'bo_sung', 'slide p.7', fixed=False))
add(mcq(Q('Slide Ch.4 tr.8: vì sao cần dự đoán nhiệt độ điểm sương của sản phẩm cháy?', 'Slide Ch.4 p.8: why is it important to predict the dew-point temperature of the combustion products?'),
        [opt('Vì các giọt nước ngưng thường kết hợp với SO₂ trong khí cháy, tạo axit sunfuric ăn mòn mạnh.'), opt('Vì nước ngưng làm tăng nhiệt độ ngọn lửa.'), opt('Vì dưới điểm sương nitơ bắt đầu phản ứng với oxy.'), opt('Vì điểm sương quyết định số mol không khí lý thuyết.')], 0,
        B('Slide tr.8: dưới điểm sương hơi nước ngưng, giọt nước hòa với SO₂ (nếu có) thành axit sunfuric rất ăn mòn nên phải biết điểm sương để giữ ống khói và bộ trao đổi nhiệt trên nhiệt độ đó. Ngưng tụ không làm tăng nhiệt độ ngọn lửa và không liên quan đến N₂ hay a_th.', 'Slide p.8: below the dew point water vapor condenses and the droplets combine with any SO₂ to form highly corrosive sulfuric acid, so the stack and heat exchangers must be kept above it. Condensation does not raise the flame temperature and has nothing to do with N₂ or a_th.'),
        1, TP['dew'], S(8, 'điểm sương và ăn mòn', 'dew point and corrosion'), 'bo_sung', 'slide p.8'))
add(mcq(Q('Slide Ch.4 tr.10 nêu nhiệt độ bốc cháy tối thiểu trong không khí: xăng 260 °C, cacbon 400 °C, hiđrô 580 °C, CO 610 °C, metan 630 °C. Chất nào cần nhiệt độ bốc cháy tối thiểu CAO NHẤT?', 'Slide Ch.4 p.10 gives the minimum ignition temperatures in air: gasoline 260 °C, carbon 400 °C, hydrogen 580 °C, CO 610 °C, methane 630 °C. Which substance needs the HIGHEST minimum ignition temperature?'),
        [opt('Methane (630 °C)'), opt('Carbon monoxide (610 °C)'), opt('Hydrogen (580 °C)'), opt('Gasoline (260 °C)')], 0, B('Theo slide tr.10 metan có nhiệt độ bốc cháy tối thiểu cao nhất (630 °C), rồi CO (610), hiđrô (580), cacbon (400) và xăng thấp nhất (260). Nhiên liệu phải được đưa trên nhiệt độ này mới cháy; tiếp xúc với oxy thôi chưa đủ.', 'By slide p.10 methane has the highest minimum ignition temperature (630 °C), then CO (610), hydrogen (580), carbon (400) and gasoline the lowest (260). The fuel must be brought above this temperature to burn; contact with oxygen alone is not enough.'),
        1, TP['basic'], S(10, 'nhiệt độ bốc cháy', 'ignition temperatures'), 'bo_sung', 'slide p.10'))
add(tf(Q('Slide Ch.4 tr.10: ngoài việc vượt nhiệt độ bốc cháy, hỗn hợp nhiên liệu–không khí còn phải nằm trong một khoảng nồng độ thích hợp mới bắt đầu cháy (khí thiên nhiên: khoảng 5–15 % trong không khí).', 'Slide Ch.4 p.10: besides exceeding the ignition temperature the fuel–air mixture must also lie in a suitable concentration range to begin burning (natural gas: about 5–15 percent in air).'), True,
       B('Đúng. Slide tr.10: khí thiên nhiên không cháy trong không khí nếu nồng độ nhỏ hơn 5 % hoặc lớn hơn khoảng 15 %, dù đã trên nhiệt độ bốc cháy.', 'True. Slide p.10: natural gas does not burn in air at concentrations below 5 percent or above about 15 percent, even above the ignition temperature.'),
       1, TP['basic'], S(10, 'giới hạn cháy 5–15 %', 'flammability range 5–15 %'), 'bo_sung', 'slide p.10'))
add(tf(Q('Slide Ch.4 tr.16: trong phương trình C₈H₁₈ + 20(O₂ + 3,76 N₂) → …, hệ số 20 là số mol KHÔNG KHÍ.'.replace('3,76', '3.76'), 'Slide Ch.4 p.16: in the equation C₈H₁₈ + 20(O₂ + 3.76 N₂) → …, the coefficient 20 is the number of moles of AIR.'), False,
       B('Sai. Hệ số 20 là số mol O₂; số mol không khí = 20 + 20 × 3,76 = 95,2 kmol (= 20 × 4,76). Nhầm hai số này làm sai AF.', 'False. The coefficient 20 is the number of moles of O₂; the moles of air = 20 + 20 × 3.76 = 95.2 kmol (= 20 × 4.76). Confusing the two gives a wrong AF.'),
       1, TP['af'], S(16, 'hệ số 20 là mol O₂', 'the coefficient 20 is moles of O₂'), 'bo_sung', 'slide p.16'))
add(mcq(Q('Slide Ch.4 tr.19: nguyên nhân nào dưới đây KHÔNG nằm trong các nguyên nhân gây cháy không hoàn toàn mà slide nêu?', 'Slide Ch.4 p.19: which of the following is NOT among the causes of incomplete combustion named on the slide?'),
        [opt('Có quá nhiều N₂ trong không khí cấp vào.'), opt('Thiếu oxy.'), opt('Trộn không đủ trong thời gian nhiên liệu và oxy tiếp xúc ngắn.'), opt('Phân ly ở nhiệt độ cao.')], 0,
        B('Slide tr.19 nêu: thiếu oxy; có oxy nhiều hơn mức cần (nhưng trộn không đủ); trộn không đủ trong thời gian tiếp xúc ngắn; phân ly (nhất là ở nhiệt độ cao). N₂ dư không phải nguyên nhân gây cháy không hoàn toàn (nó chỉ hạ nhiệt độ). Lưu ý: nguyên nhân thật của trường hợp có dư oxy là trộn không đủ (Cengel §15-2).', 'Slide p.19 lists: insufficient oxygen; more oxygen than needed (but insufficient mixing); insufficient mixing in the short contact time; dissociation (especially at high temperature). Extra N₂ is not a cause of incomplete combustion (it only lowers the temperature). Note: the real cause when oxygen is in excess is insufficient mixing (Cengel §15-2).'),
        2, TP['air'], S(19, 'nguyên nhân cháy không hoàn toàn', 'causes of incomplete combustion'), 'bo_sung', 'slide p.19 + Cengel §15-2'))
add(tf(Q('Slide Ch.4 tr.20: khi thiếu oxy, hiđrô trong nhiên liệu thường vẫn cháy hết thành H₂O, còn một phần cacbon thành CO hoặc muội than.', 'Slide Ch.4 p.20: when oxygen is short, the hydrogen of the fuel normally still burns completely to H₂O, while part of the carbon ends up as CO or soot.'), True,
       B('Đúng (tr.20): oxy có ái lực với hiđrô lớn hơn với cacbon, nên H đi hết vào H₂O, còn C có thể thành CO hoặc muội. Vì vậy trong bài cháy thiếu không khí ta coi toàn bộ H thành H₂O rồi chia O còn lại cho CO₂ và CO.', 'True (p.20): oxygen has a greater tendency to combine with hydrogen than with carbon, so all H goes to H₂O while C may become CO or soot. That is why in air-deficient problems we put all H into H₂O and share the remaining O between CO₂ and CO.'),
       2, TP['air'], S(20, 'H cháy trước C', 'hydrogen burns before carbon'), 'bo_sung', 'slide p.20'))
add(mcq(Q('Slide Ch.4 tr.23–24: đúng lượng không khí lý thuyết là 100 % không khí lý thuyết. Lượng không khí 150 % lý thuyết và 90 % lý thuyết tương ứng là:', 'Slide Ch.4 p.23–24: the stoichiometric amount of air is 100 percent theoretical air. 150 percent and 90 percent theoretical air correspond to:'),
        [opt('50 % không khí thừa; 10 % thiếu không khí'), opt('150 % không khí thừa; 90 % thiếu không khí'), opt('50 % thiếu không khí; 10 % không khí thừa'), opt('15 % không khí thừa; 9 % thiếu không khí')], 0,
        B('% thừa = % lý thuyết − 100 %: 150 % lý thuyết = 50 % thừa; % thiếu = 100 % − % lý thuyết: 90 % lý thuyết = 10 % thiếu (tr.23–24). 200 % thừa = 300 % lý thuyết.', 'Percent excess = percent theoretical − 100 %: 150 % theoretical = 50 % excess; percent deficiency = 100 % − percent theoretical: 90 % theoretical = 10 % deficiency (p.23–24). 200 % excess = 300 % theoretical.'),
        1, TP['air'], S('23–24', '% thừa, % thiếu, % lý thuyết', 'percent excess, deficiency, theoretical'), 'bo_sung', 'slide p.23-24'))
add(mcq(Q('Slide Ch.4 tr.24: hệ số tương đương (equivalence ratio) φ là tỉ số giữa tỉ lệ nhiên liệu–không khí thực tế và tỉ lệ nhiên liệu–không khí hợp thức. Một hỗn hợp cháy với 125 % không khí lý thuyết có φ bằng:', 'Slide Ch.4 p.24: the equivalence ratio φ is the ratio of the actual fuel–air ratio to the stoichiometric fuel–air ratio. A mixture burned with 125 percent theoretical air has φ equal to:'),
        [opt('0.80 (hỗn hợp nghèo)' if False else '0.80 (lean)'), opt('1.25 (rich)'), opt('0.25 (lean)'), opt('1.00 (stoichiometric)')], 0,
        B('φ = (F/A)thực/(F/A)lt = (A/F)lt/(A/F)thực = 1/1,25 = 0,80 < 1: hỗn hợp nghèo (thừa không khí). φ > 1 là giàu (thiếu không khí). 1,25 là nghịch đảo (nhầm φ với % lý thuyết).', 'φ = (F/A)act/(F/A)st = (A/F)st/(A/F)act = 1/1.25 = 0.80 < 1: a lean mixture (air in excess). φ > 1 is rich (air deficiency). 1.25 is the inverse (φ confused with the percent theoretical air).'),
        2, TP['air'], S(24, 'hệ số tương đương', 'equivalence ratio'), 'bo_sung', 'slide p.24 + script'))
add(mcq(Q('Slide Ch.4 tr.26: máy phân tích khí Orsat cho kết quả theo cơ sở nào, và vì sao?', 'Slide Ch.4 p.26: on which basis does the Orsat gas analyzer report its result, and why?'),
        [opt('Cơ sở khô: mẫu khí được thu trên nước và bão hòa hơi nước nên hơi nước không được tính vào kết quả; lượng H₂O sinh ra suy ra từ cân bằng phương trình.'), opt('Cơ sở ướt: mẫu giữ nguyên hơi nước ở nhiệt độ buồng đốt.'), opt('Cơ sở khối lượng: máy đo khối lượng từng khí.'), opt('Cơ sở khô: vì máy hấp thụ H₂O đầu tiên rồi mới đo CO₂.')], 0,
        B('Orsat báo thành phần thể tích trên cơ sở khô (tr.26; Cengel: mẫu thu trên nước, bão hòa hơi nước nên áp suất hơi không đổi và bị bỏ qua). Phần thể tích bằng phần mol với khí lý tưởng; H₂O sinh ra suy ra từ cân bằng (hệ số b trong Ví dụ 15–4). Không đo khối lượng.', 'Orsat reports volume fractions on a dry basis (p.26; Cengel: the sample is collected over water and stays saturated so the vapor pressure is constant and ignored). Volume fraction equals mole fraction for ideal gases; the H₂O formed is found from the balance (coefficient b of Example 15–4). It does not measure mass.'),
        2, TP['rev'], S(26, 'máy phân tích Orsat', 'Orsat analyzer'), 'bo_sung', 'slide p.26 + Cengel §15-2'))
add(mcq(Q('Slide Ch.4 tr.31: nhiệt độ điểm sương của sản phẩm cháy (khí lý tưởng) bằng:', 'Slide Ch.4 p.31: the dew-point temperature of the combustion products (ideal gases) equals:'),
        [opt('nhiệt độ bão hòa của nước ứng với áp suất riêng phần của hơi nước, P_v = (N_v/N_prod) P_prod'), opt('nhiệt độ bão hòa của nước ứng với áp suất tổng của sản phẩm'), opt('nhiệt độ mà tại đó N₂ ngưng tụ'), opt('nhiệt độ ngọn lửa trừ 100 °C')], 0,
        B('Điểm sương = T_sat(P_v) với P_v = y_v P_prod = (N_v/N_prod) P_prod (tr.31–32). Dùng áp suất tổng cho điểm sương gần 100 °C ở 100 kPa, sai.', 'Dew point = T_sat(P_v) with P_v = y_v P_prod = (N_v/N_prod) P_prod (p.31–32). Using the total pressure gives about 100 °C at 100 kPa, which is wrong.'),
        1, TP['dew'], S('31–32', 'định nghĩa điểm sương', 'definition of dew point'), 'bo_sung', 'slide p.31-32', fixed=False))
add(mcq(Q('Slide Ch.4 tr.43: trạng thái chuẩn dùng làm mốc chung cho các chất trong phản ứng hóa học là:', 'Slide Ch.4 p.43: the standard reference state used as a common reference for all substances in chemical reactions is:'),
        [opt('25 °C (77 °F) và 1 atm'), opt('0 °C và 1 atm'), opt('25 °C và 1 MPa'), opt('0 K và 1 atm')], 0, B('Trạng thái chuẩn (standard reference state) là 25 °C và 1 atm, ký hiệu bằng dấu ° (h°, u°) (tr.43). Bảng A-18…A-23 vì vậy cho h̄(298 K) và ta dùng hiệu h̄(T) − h̄(298 K) (tr.44).', 'The standard reference state is 25 °C and 1 atm, marked by the superscript ° (h°, u°) (p.43). Tables A-18…A-23 therefore give h̄(298 K) and we use the difference h̄(T) − h̄(298 K) (p.44).'),
        1, TP['enth'], S(43, 'trạng thái chuẩn', 'standard reference state'), 'bo_sung', 'slide p.43'))
add(mcq(Q('Slide Ch.4 tr.49: chất nào sau đây có entanpi hình thành h̄_f° KHÁC không ở trạng thái chuẩn (bảng A-26)?', 'Slide Ch.4 p.49: which of the following has a NON-zero enthalpy of formation h̄_f° at the standard state (Table A-26)?'),
        [opt('CO₂'), opt('O₂'), opt('N₂'), opt('H₂')], 0, B('Quy ước (tr.49): mọi nguyên tố bền (O₂, N₂, H₂, C graphit) có h̄_f° = 0; CO₂ là hợp chất nên h̄_f° = −393 520 kJ/kmol (A-26).', 'Convention (p.49): every stable element (O₂, N₂, H₂, C graphite) has h̄_f° = 0; CO₂ is a compound so h̄_f° = −393,520 kJ/kmol (A-26).'),
        1, TP['enth'], S(49, 'h_f = 0 cho nguyên tố bền', 'h_f = 0 for stable elements'), 'bo_sung', 'slide p.49 + A-26', fixed=False))
add(tf(Q('Slide Ch.4 tr.50: entanpi hình thành h̄_f° của một hợp chất có giá trị ÂM nghĩa là quá trình hình thành hợp chất đó từ các nguyên tố bền tỏa nhiệt.', 'Slide Ch.4 p.50: a NEGATIVE enthalpy of formation h̄_f° of a compound means that its formation from the stable elements releases heat.'), True,
       B('Đúng (tr.50): giá trị âm nghĩa là nhiệt được giải phóng khi hình thành hợp chất từ các nguyên tố bền; giá trị dương (như C₂H₂: +226 730 kJ/kmol) nghĩa là hấp thụ nhiệt.', 'True (p.50): a negative value means heat is released when the compound forms from its stable elements; a positive value (such as C₂H₂: +226,730 kJ/kmol) means heat is absorbed.'),
       1, TP['enth'], S(50, 'dấu của h_f', 'sign of h_f'), 'bo_sung', 'slide p.50 + A-26'))
add(mcq(Q('Slide Ch.4 tr.51–52: nhiệt trị cao HHV và nhiệt trị thấp LHV khác nhau ở chỗ:', 'Slide Ch.4 p.51–52: the higher heating value HHV and the lower heating value LHV differ in that:'),
        [opt('HHV tính khi H₂O trong sản phẩm ở thể lỏng, LHV khi ở thể hơi; HHV = LHV + m·h_fg'), opt('HHV tính khi H₂O ở thể hơi, LHV khi ở thể lỏng'), opt('HHV tính ở áp suất cao hơn, LHV ở áp suất thấp hơn'), opt('HHV gồm cả năng lượng hạt nhân của nhiên liệu')], 0,
        B('Nhiệt trị = |h_C|; khi H₂O sản phẩm ở thể lỏng ta có HHV, khi ở thể hơi ta có LHV; HHV = LHV + (m h_fg)_H₂O, m là khối lượng H₂O trong sản phẩm trên 1 kg nhiên liệu (tr.51–52). Với nhiên liệu không có H (C, CO) hai giá trị bằng nhau.', 'Heating value = |h_C|; with liquid H₂O in the products it is the HHV, with vapor the LHV; HHV = LHV + (m h_fg)_H₂O, with m the mass of H₂O in the products per kg of fuel (p.51–52). For fuels without hydrogen (C, CO) the two are equal.'),
        1, TP['enth'], S('51–52', 'HHV và LHV', 'HHV and LHV'), 'bo_sung', 'slide p.51-52', fixed=False))
